#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long cap;
};

struct Dinic {
    int n;
    vector<vector<Edge>> adj;
    vector<int> level, start;

    Dinic(int n): n(n), adj(n), level(n), start(n) {}

    void add_edge(int u, int v, long long cap) {
        adj[u].push_back({v, (int)adj[v].size(), cap});
        adj[v].push_back({u, (int)adj[u].size() - 1, 0});
    }

    bool bfs(int s, int t) {
        for (int i = 0; i < n; i++) level[i] = -1;
        level[s] = 0;
        queue<int> q; q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &e : adj[u]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    long long sendFlow(int u, int t, long long flow) {
        if (u == t) return flow;
        for (int &i = start[u]; i < (int)adj[u].size(); i++) {
            auto &e = adj[u][i];
            if (e.cap > 0 && level[e.to] == level[u] + 1) {
                long long curr_flow = min(flow, e.cap);
                long long temp_flow = sendFlow(e.to, t, curr_flow);
                if (temp_flow > 0) {
                    e.cap -= temp_flow;
                    adj[e.to][e.rev].cap += temp_flow;
                    return temp_flow;
                }
            }
        }
        return 0;
    }

    long long maxFlow(int s, int t) {
        long long total = 0;
        while (bfs(s, t)) {
            for (int i = 0; i < n; i++) start[i] = 0;
            while (long long flow = sendFlow(s, t, LLONG_MAX))
                total += flow;
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    vector<int> ii(k);
    for (int h = 0; h < k; h++) {
        cin >> ii[h];
        ii[h]--;
    }
    vector<vector<int>> adjacency(n);
    for (int h = 0; h < m; h++) {
        int i, j;
        cin >> i >> j;
        i--; j--;
        adjacency[i].push_back(j);
        adjacency[j].push_back(i);
    }

    int t = n + k + 1;
    int totalNodes = n * t + 1;
    long long totalEdges = k + (long long)(m * 2 * k + n) * (t - 1);

    Dinic graph(totalNodes);

    auto buildGraph = [&](const vector<vector<int>> &adj, int n, int k, int c, int d, int t) {
        // Build the layered graph
        for (int i = 0; i < n; i++) {
            for (int layer = 0; layer < t; layer++) {
                int node = i * t + layer;
                if (layer < t - 1) {
                    // connect node to next layer with capacity c
                    graph.add_edge(node, node + n * t, c);
                }
            }
        }
        // Connect source to the last layer of each node
        int source = totalNodes - 1;
        for (int i = 0; i < n; i++) {
            int node = i * t + t - 1;
            graph.add_edge(source, node, LLONG_MAX);
        }
        // Connect the first layer of each node to sink
        int sink = 0;
        for (int i = 0; i < n; i++) {
            int node = i * t;
            graph.add_edge(node, sink, LLONG_MAX);
        }
        // Add edges for adjacency
        for (int i = 0; i < n; i++) {
            for (int neighbor : adjacency[i]) {
                for (int layer = 0; layer < t - 1; layer++) {
                    int u = i * t + layer;
                    int v = neighbor * t + layer + 1;
                    graph.add_edge(u, v, LLONG_MAX);
                }
            }
        }
    };

    buildGraph(adjacency, n, k, c, d, t);
    int source = totalNodes - 1;
    int sink = 0;
    cout << graph.maxFlow(source, sink) << "\n";

    return 0;
}

